<?php
declare(strict_types=1);
namespace FavoriteCMS\Central;
final class Ui {
 static function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
 static function styles():string{return '<style>
.fcp{--fc-bg:var(--admin-bg,#f4f7fc);--fc-panel:var(--admin-surface,#fff);--fc-line:var(--admin-border,#d9e2f0);--fc-text:var(--admin-text,#172b46);--fc-muted:var(--admin-text-muted,#667991);color:var(--fc-text);background:var(--fc-bg);font:14px/1.6 system-ui,sans-serif;min-width:0}
.plugin-page-card:has(.fcp){background:transparent!important;padding:0!important;border:0!important;box-shadow:none!important}
.page-header:has(+ .plugin-page-card .fcp){display:none}.fcp nav a.active{color:#fff!important}.fcp *{box-sizing:border-box}.fcp h1,.fcp h2,.fcp h3,.fcp p{margin:0}.fcp h1{font-size:28px;letter-spacing:-.7px}.fcp h2{font-size:20px}.fcp small,.fcp p{color:var(--fc-muted)}.fcp header{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.fcp .eyebrow{font-size:10px;letter-spacing:2px;color:#448dff;font-weight:800}
.fcp nav{display:flex;flex-wrap:wrap;gap:6px;padding:8px;border:1px solid var(--fc-line);border-radius:12px;margin:20px 0}.fcp nav a{padding:9px 13px;text-decoration:none;color:var(--fc-muted);border-radius:8px;font-weight:650}.fcp nav a.active{background:#246cec;color:#fff}
.fcp .card{padding:22px;border:1px solid var(--fc-line);border-radius:14px;background:var(--fc-panel);margin:16px 0;box-shadow:none}.fcp .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.fcp .grid .card{margin:0}.fcp .metric{font-size:30px;font-weight:750}
.fcp label{display:block;font-weight:650;margin:14px 0 5px}.fcp input,.fcp select,.fcp textarea{display:block;width:100%;padding:10px 12px;min-height:42px;background:var(--fc-bg);color:var(--fc-text);border:1px solid var(--fc-line);border-radius:8px;font:inherit}.fcp input[type=checkbox]{display:inline-block;width:18px;min-height:18px}.fcp button,.fcp .button{display:inline-flex;align-items:center;justify-content:center;padding:10px 15px;min-height:42px;border:1px solid var(--fc-line);border-radius:8px;font:600 12px system-ui;text-decoration:none;background:var(--fc-panel);color:var(--fc-text);white-space:nowrap;cursor:pointer}.fcp button.primary,.fcp .button.primary{background:#246cec;color:white;border-color:#246cec}.fcp button.danger{background:#a42a40;color:white;border-color:#a42a40}.fcp .actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}
.fcp .notice{padding:13px 16px;border:1px solid var(--fc-line);border-radius:9px;background:var(--fc-panel);margin:15px 0}.fcp .error{border-color:#b4344b;color:#dc5269}.fcp table{width:100%;border-collapse:collapse;text-align:left}.fcp td,.fcp th{padding:13px 10px;border-bottom:1px solid var(--fc-line);overflow-wrap:anywhere}.fcp th{font-size:11px;text-transform:uppercase;color:var(--fc-muted)}.fcp .table{overflow:auto}.fcp .clip{max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fcp code{font-size:12px;overflow-wrap:anywhere}.fcp details{margin:16px 0}.fcp .badge{display:inline-block;padding:3px 9px;border-radius:20px;background:#246cec20;font-size:11px}.fcp .inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.fcp .inline form{margin:0}.fcp .inline input{width:auto}
@media(max-width:700px){.fcp header{align-items:flex-start;flex-direction:column}.fcp h1{font-size:24px}.fcp .card{padding:16px}.fcp nav{display:grid;grid-template-columns:1fr 1fr}.fcp nav a{text-align:center}.fcp .table table,.fcp .table tbody,.fcp .table tr,.fcp .table td{display:block}.fcp .table thead{display:none}.fcp .table tr{border:1px solid var(--fc-line);border-radius:10px;margin:10px 0;padding:8px}.fcp .table td{border:0;padding:6px}.fcp .clip{max-width:100%}}
</style>';}
 static function field(string $name,string $label,mixed $value='',string $type='text',bool $required=true):string{return '<label>'.self::e($label).'<input type="'.self::e($type).'" name="'.self::e($name).'" value="'.($type==='password'?'':self::e($value)).'" '.($required?'required':'').'></label>';}
 static function token(string $action):string{return '<input type="hidden" name="_token" value="'.self::e(csrf_token()).'"><input type="hidden" name="action" value="'.self::e($action).'">';}
 static function select(string $name,string $label,array $options,string $current):string{$h='<label>'.self::e($label).'<select name="'.self::e($name).'">';foreach($options as$k=>$v)$h.='<option value="'.self::e($k).'" '.($current===(string)$k?'selected':'').'>'.self::e($v).'</option>';return $h.'</select></label>';}
 static function document(string $title,string $body):string{return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).'</title></head><body style="margin:0;background:#f4f7fc"><main class="fcp" style="max-width:1100px;margin:30px auto;padding:20px">'.self::styles().$body.'</main></body></html>';}
}
